import sys

def base36_increment(s: str) -> str:
    """Increment a base36-encoded string by 1."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        c = chars[i]
        if '0' <= c <= '9':
            if c < '9':
                chars[i] = chr(ord(c) + 1)
                return ''.join(chars)
            else:
                chars[i] = 'A'
                return ''.join(chars)
        elif 'A' <= c <= 'Z':
            if c < 'Z':
                chars[i] = chr(ord(c) + 1)
                return ''.join(chars)
            else:
                chars[i] = '0'
                # carry to next digit (handled by loop)
        elif 'a' <= c <= 'z':
            if c < 'z':
                chars[i] = chr(ord(c) + 1)
                return ''.join(chars)
            else:
                chars[i] = '0'
                # carry to next digit
        else:
            raise ValueError(f"Invalid base36 character: {c}")
    # If we overflow all digits, prepend '1'
    return '1' + ''.join(chars)


def main():
    try:
        with open('ids.txt', 'r') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    if not last_id.startswith('ORD-') or len(last_id) != 8:
        print(f"Error: unexpected id format: {last_id}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    next_suffix = base36_increment(suffix)
    print(f"ORD-{next_suffix}")


if __name__ == '__main__':
    main()
