import string

ALPHABET = string.digits + string.ascii_uppercase  # 0-9, A-Z


def to_base36(n, width):
    if n == 0:
        digits = "0"
    else:
        digits = ""
        while n:
            n, rem = divmod(n, 36)
            digits = ALPHABET[rem] + digits
    return digits.zfill(width)


def next_id(prefix="ORD-", width=4):
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]
    if not lines:
        suffix = "0" * width
    else:
        last = lines[-1]
        if not last.startswith(prefix):
            raise ValueError(f"Unexpected id format: {last!r}")
        suffix = last[len(prefix):]
        if len(suffix) != width:
            raise ValueError(f"Unexpected id width: {last!r}")
    n = int(suffix, 36) + 1
    return prefix + to_base36(n, width)


if __name__ == "__main__":
    print(next_id())
