import sys

def to_base36(num):
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    result = ''
    for _ in range(4):
        result = chars[num % 36] + result
        num //= 36
    return result

def from_base36(s):
    return int(s, 36)

def main():
    with open('ids.txt') as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        next_id = '0000'
    else:
        last_line = lines[-1]
        suffix = last_line.split('-')[1]
        num = from_base36(suffix)
        next_id = to_base36(num + 1)

    print(f'ORD-{next_id}')

if __name__ == '__main__':
    main()

