"""Generate manifest.json with SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
RELEASE_DIR = REPO_ROOT / "release"
MANIFEST_PATH = REPO_ROOT / "manifest.json"


def sha256_digest(path: Path) -> str:
    """Return the lowercase hex SHA-256 digest of *path*."""
    h = hashlib.sha256()
    with path.open("rb") as f:
        while chunk := f.read(65536):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest = {}
    # Walk release/ in sorted order for deterministic output.
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel_path = str(path.relative_to(REPO_ROOT))
            manifest[rel_path] = sha256_digest(path)

    MANIFEST_PATH.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(f"Wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

