#!/usr/bin/env python3
"""List report filenames in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_sort_key(filename: str) -> tuple[int, str]:
    """Sort key: numeric prefix first, then lexicographic for ties."""
    match = re.search(r"(\d+)", filename)
    num = int(match.group(1)) if match else 0
    return (num, filename)


def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"error: '{REPORTS_DIR}' directory not found", file=__import__("sys").stderr)
        raise SystemExit(1) from None

    files = sorted(
        (f for f in entries if os.path.isfile(os.path.join(REPORTS_DIR, f))),
        key=report_sort_key,
    )
    for f in files:
        print(f)


if __name__ == "__main__":
    main()

