"""Rotate log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' prefix from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = as_of - 7 * 86400  # 7 days in seconds
    cutoff_dt = datetime.fromtimestamp(cutoff, tz=timezone.utc)

    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    archive_lines: list[str] = []
    keep_lines: list[str] = []

    for line in lines:
        dt = parse_timestamp(line)
        if dt is not None and dt < cutoff_dt:
            archive_lines.append(line)
        else:
            keep_lines.append(line)

