import sys
import os
from datetime import datetime, timedelta, timezone


def parse_log_timestamp(line: str) -> datetime | None:
    """Extract the leading YYYY-MM-DD HH:MM:SS timestamp from a log line."""
    if len(line) < 19 or line[4] != '-' or line[7] != '-' or line[13] != ':' or line[16] != ':':
        return None
    try:
        return datetime.strptime(line[:19], '%Y-%m-%d %H:%M:%S').replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(days=7)

    repo_root = os.path.dirname(os.path.abspath(__file__))
    app_log_path = os.path.join(repo_root, 'app.log')
    archive_log_path = os.path.join(repo_root, 'archive.log')

    if not os.path.isfile(app_log_path):
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    with open(app_log_path, 'r') as f:
        lines = f.readlines()

    keep = []
    archive_lines = []

    for line in lines:
        ts = parse_log_timestamp(line)
        if ts is not None and ts < cutoff:
            archive_lines.append(line)
        else:
            keep.append(line)

    # Append archived entries to archive.log in original order
    if archive_lines:
        with open(archive_log_path, 'a') as f:
            f.writelines(archive_lines)

    # Rewrite app.log with remaining entries in original order
    with open(app_log_path, 'w') as f:
        f.writelines(keep)

    print(f"Rotated {len(archive_lines)} entries to archive.log, kept {len(keep)} in app.log")


if __name__ == '__main__':
    main()

